// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2024, "6-7", [{"author":"И. Иткин","question":"Я просто __________, как решается эта задача!","choices":["ума не переложу","ума не предложу","ума не проложу","ума не приложу","ума не прилажу"],"key":"Г","review":["Устойчивое выражение","Герой хочет сказать, что не понимает, как решить задачу. В русском языке такую растерянность выражают оборотом со словом «ума».","Правильно «ума не приложу». Другие формы похожи по звучанию, но не входят в это выражение."]},{"author":"Л. Фёдорова","question":"Какого слова не существует?","choices":["сводка","сборка","свалка","сноска","все слова (А)–(Г) существуют"],"key":"Д","review":["Четыре существительных","«Сводка» — компактный обзор сведений, «сборка» — соединение частей или результат этой работы.","«Свалка» — место для мусора, «сноска» — примечание к тексту. Есть все четыре слова."]},{"author":"А. Пиперски","question":"В каком выражении обычно не пропускают слово час?","choices":["четыре часа утра","десять часов утра","три часа дня","шесть часов вечера","одиннадцать часов вечера"],"key":"В","review":["Название часа","Проверим, как звучат варианты без «часов». «В четыре утра», «в десять утра», «в шесть вечера» и «в одиннадцать вечера» понятны.","«В три дня» может относиться к сроку, например «уложиться в три дня». Точное время обычно называют «в три часа дня»."]},{"author":"А. Ковалёва","question":"Какая фраза точно не относится к мальчику?","choices":["Кто тут плакса?","Саша умница.","Женя чистюля.","Ты красавица.","Валя белоручка"],"key":"Г","review":["Слова о человеке","«Плакса», «умница», «чистюля» и «белоручка» подходят человеку любого пола. Имена Саша, Женя и Валя тоже бывают у мальчиков.","Слово «красавица» женского рода. Мальчика обычно назвали бы красавцем."]},{"author":"А. Сомин","question":"Якутское слово баhыыба и слово späʹsseb колтта-саамского языка, на котором говорят на севере Финляндии и в Мурманской области, восходят к одному и тому же русскому слову и используются __________.","choices":["при приветствии","при прощании","для извинения","для выражения благодарности","для выражения просьбы"],"key":"Г","review":["Два заимствования","В словах видны отчётливые части, похожие на звуки русского «спасибо»: сближают их сочетания согласных и ударные гласные.","Общим источником является «спасибо». Это слово произносят в знак благодарности."]},{"author":"О. Подлесская","question":"Автомобиль — автомашина; зоопарк — зоосад; фотография — _____. Заполните пропуск.","choices":["фотобумага","фотокарточка","фотоаппарат","фотостудия","фотолюбитель"],"key":"Б","review":["Слова с «фото-»","В данных парах оба слова называют одно и то же. Автомобиль — это автомашина, зоопарк — зоосад.","Снимок называют и фотографией, и фотокарточкой. Фотоаппарат делает снимок, а фотобумага служит для его печати."]},{"author":"О. Подлесская","question":"Одна актриса сказала в интервью: «Я не хочу это замалкивать». А как надо было сказать?","choices":["помалкивать","замолкивать","замолкнуть","замалчивать","помалчивать"],"key":"Г","review":["Слова о молчании","Говорящая хочет открыто обсуждать тему. Ей нужен глагол со смыслом «намеренно обходить тему молчанием».","Об этом говорят «замалчивать это». «Замолкнуть» значит перестать говорить вообще."]},{"author":"А. Остроумова","question":"В каком словосочетании слово прямой употреблено в своём прямом значении?","choices":["прямое значение","прямые волосы","прямая противоположность","прямой эфир","прямой угол"],"key":"Б","review":["Значения слова «прямой»","В буквальном смысле прямой предмет не изгибается. Это можно увидеть у волос, которые не вьются.","У «прямого эфира» речь о времени передачи, а «прямой угол» — специальное название угла 90°. Буквальную форму описывают «прямые волосы»."]},{"author":"Ф. Тучак","question":"В хваршинском языке слово гъудулабосос означает ‘зелёный’. Что означает слово гъудул?","choices":["‘дом’","‘гора’","‘овца’","‘поле’","‘солнце’"],"key":"Г","review":["Цвет из названия предмета","В слове для зелёного цвета легко выделить начало «гъудул». Среди предложенных слов ищем предмет, обычно ассоциирующийся с зелёным.","Покрытое травой поле даёт нужную связь. Гъудул означает «поле»."]},{"author":"А. Ковалёва","question":"В какой фразе допущена ошибка?","choices":["«Ребята из другого класса пошли в поход, а мы куда пойдём?» — спросил Петя.","«Пойдёмте завтра в кино», — предложила Люся.","«Пошлите лучше всем классом в цирк», — сказал Боря.","«Нет, давайте пойдём в театр», — сказала Вера.","«Пошлите, пожалуйста, сообщение всем ребятам», — напомнила Оля"],"key":"В","review":["Приглашение или отправка","Формы «пойдём» и «пойдёмте» связаны с движением и могут быть приглашением. Они подходят к походу, кино, цирку и театру.","«Пошлите» происходит от «послать», поэтому уместно с сообщением. Приглашать в цирк надо словом «пойдёмте». Ошибка в В."]},{"author":"А. Пиперски","question":"И. С. Тургенев описывает Муму как «собачку испанской породы». А как такая собака называется сейчас?","choices":["дворняжка","болонка","сенбернар","йоркширский терьер","спаниель"],"key":"Д","review":["Название породы Муму","«Собачка испанской породы» подсказывает географическое происхождение старого названия. Ищем современное слово со звучанием, связанным с Испанией.","Название «спаниель» исторически связано со словом для испанской собаки. Оно подходит к описанию Тургенева."]},{"author":"Л. Фёдорова","question":"Что обычно уносят, испугавшись?","choices":["крышу","мозги","голову","руки","ноги"],"key":"Д","review":["Оборот об испуге","В вопросе о том, что «уносят», спрятано устойчивое выражение о быстром бегстве.","«Унести ноги» значит успеть убежать. Так могут сказать о том, кто испугался и поспешил прочь."]},{"author":"Н. Лебедева","question":"В каком примере выделенное слово имеет не такое значение, как в остальных?","choices":["Чистили пёрышки разноцветные попугаи, возвращались с ночной <strong>охоты</strong> сытые хищники. (В. Постников)","Услыхав собаку, лисичка, конечно, сейчас же бросила <strong>охоту</strong> за русаком. (М. Пришвин)","Старик стоял среди дороги и крикнул мне: «Вернись!» Я еле через ветер услышал. Без <strong>охоты</strong> лошади тронули. (Б. Житков)","Марсик сидел на подоконнике и «считал» ворон. Появление каждой птицы было сигналом к большой <strong>охоте</strong>. (М. Аромштам)","Было уже начало декабря, и <strong>охота</strong> на норок, если они тут водились, была на исходе. (М. Пришвин)"],"key":"В","review":["Два значения «охоты»","В четырёх примерах слово связано с преследованием зверя или птицы. Хищники, лиса и ловцы норок ищут добычу.","У Житкова лошади трогаются «без охоты», то есть без желания, неохотно. Здесь никто не охотится."]},{"author":"О. Подлесская","question":"В какой паре точно представлены разные по значению слова?","choices":["наверно — наверное","посредине — посередине","отмстить — отомстить","ванна — ванная","вслед — вослед"],"key":"Г","review":["Вещь и комната","«Наверно» и «наверное», «посредине» и «посередине» могут обозначать одно и то же. Так же близки «отмстить» и «отомстить», «вслед» и «вослед».","Ванна — ёмкость, в которую набирают воду. Ванная — комната, где такая ёмкость стоит. Значения у слов различны."]},{"author":"Б. Иомдин","question":"Встретив в тексте одно незнакомое ей слово, программа породила для него, в частности, формы аквагрю и аквагрят. А что значит это слово?","choices":["жанр живописи","краска для лица","вид спорта","морское животное","быстрый танец"],"key":"Б","review":["Слово, принятое за глагол","Формы на -ю и -ят похожи на спряжение: «говорю», «говорят». Если продолжить образец, «мы» дало бы «аквагрим», как «говорим».","В тексте «аквагрим» было существительным. Это краска для рисунков на лице и сами такие рисунки."]},{"author":"Л. Фёдорова","question":"Кто обычно не считался нечистой силой?","choices":["леший","домовой","водяной","городовой","все персонажи (А)–(Г) считались нечистой силой"],"key":"Г","review":["Житель города","Леший, домовой и водяной — существа из преданий. Их имена указывают на лес, дом и воду.","Городовым называли служащего городской полиции. Это реальная профессия."]},{"author":"А. Пиперски","question":"То, что загадано в этом ребусе, бывает __________.","choices":["у шапки","у пиджака","у рубашки","у юбки","у сапога"],"key":"Д","review":["Буквы под буквой","Синяя А расположена под О. Это читается как «под О». Внутри А стоит Ш, то есть «Ш в А».","Соединяем части «под-о-ш-в-а». Подошва бывает у сапога, поэтому подходит Д."],"figure":{"condition":{"src":"assets/medvezhonok/2024/6-7-17-rebus.webp","alt":"Красная буква О над большой синей буквой А. Внутри А находится маленькая чёрная буква Ш.","width":98,"height":146}}},{"author":"О. Подлесская","question":"Испанцы говорят про горную козу: «Козу всегда тянет в горы». А какое животное упоминается в русской пословице, аналогичной по смыслу?","choices":["заяц","волк","лиса","собака","корова"],"key":"Б","review":["Пословицы о привычках","Испанская пословица говорит о том, что привычная среда по-прежнему притягивает. Козу тянет туда, где она обычно живёт.","Русская пословица «Сколько волка ни корми, он всё в лес смотрит» выражает ту же мысль. Речь в ней о волке."]},{"author":"Л. Фёдорова","question":"От какого глагола нельзя образовать другой глагол, добавив приставку?","choices":["хулиганить","клянчить","мечтать","мудрить","класть"],"key":"Д","review":["Глаголы с приставками","К четырём словам можно добавить приставку: «похулиганить», «выклянчить», «помечтать», «намудрить».","У «класть» литературные глаголы с приставкой образованы от другой основы: «положить», «сложить», «переложить». Поэтому подходит Д."]},{"author":"Е. Муравенко","question":"Даны слова: 1) <em>перстень</em>, 2) <em>перчатка</em>, 3) <em>перчёный</em>, 4) <em>перечить</em>. Какие два из них исторически родственны?","choices":["1 и 2","1 и 3","2 и 3","2 и 4","3 и 4"],"key":"А","review":["Слова от «перста»","Старинное название пальца — «перст». С ним связаны вещи, которые надевают на палец или руку.","Это перстень и перчатка. «Перчёный» образовано от «перец», а «перечить» означает возражать."]},{"author":"А. Леонтьева","question":"У глагола плескать раньше было ещё одно значение, в современном языке практически утраченное. Какое?","choices":["стегать плёткой","хлопать в ладоши","плевать","покрываться плесенью","кашлять"],"key":"Б","review":["Старинное значение","Теперь «плескать» обычно говорят о движении воды. Раньше тем же глаголом называли и действие рук.","Можно было «плескать руками», то есть хлопать в ладоши. Отсюда связь с одобрением и аплодисментами."]},{"author":"А. Сомин","question":"Что из этого может делать не только человек, но и листья деревьев?","choices":["рассуждать","анализировать","планировать","предусматривать","размышлять"],"key":"В","review":["Планировать и падать","О человеке говорят «планировать», когда он заранее намечает действия. У этого глагола есть ещё одно значение.","Лист дерева тоже может планировать: опускаться плавно, скользя в воздухе. Здесь глагол описывает полёт."]},{"author":"И. Рубанов","question":"Два века назад перочинные ножи были непременной принадлежностью у _____.","choices":["кучеров","охотников","писцов","рыболовов","электриков"],"key":"В","review":["Перочинный нож","До металлических ручек писали гусиными перьями. Их рабочий кончик нужно было подрезать и заострять.","Перочинный нож служил для того, чтобы «чинить перо». Он был необходим писцам."]},{"author":"Е. Муравенко","question":"Вставьте гласные а или о вместо пропусков: 1) к_р_бли, 2) к_р_мель, 3) к_р_мысло. В каких двух словах первые четыре буквы совпадают?","choices":["в 1-м и 2-м","в 1-м и 3-м","во 2-м и 3-м","во всех совпадают","во всех различаются"],"key":"Д","review":["Гласные в начале слова","Вставляем буквы и получаем «корабли», «карамель» и «коромысло».","Начало каждого слова состоит из четырёх букв: «кора», «кара», «коро». Они все различаются."]},{"author":"И. Иткин","question":"— Какая досада! — проворчал Холмс. — Вторая буква повреждена, и надо же такому случиться, что по соседним буквам нельзя определить, ъ это или ь! Какая последовательность букв сохранилась на попавшем в руки Холмса клочке бумаги?","choices":["…в_ед…","...в_ез…","…в_ет…","…в_ех…","ошибается даже Холмс: выбрать между ъ и ь можно во всех этих случаях"],"key":"А","review":["Твёрдый или мягкий знак","Проверим сочетание «в_ед». Твёрдый знак в нём возможен в слове «въедаться», после приставки в-.","С мягким знаком то же буквенное окружение есть в названии города Вьедма. По обрывку с буквами В, Е и Д нельзя выбрать между знаками."]},{"author":"Е. Муравенко","question":"Учитель объяснил, что в некоторых случаях перед суффиксом -к- вместо двойной согласной пишется одна согласная буква, например: колонна — колонка, и попросил ребят привести свои примеры. Аня сказала: оперетта — оперетка, Боря: финн — финка, Вера: касса — каска, Гриша: масса — маска. Кто привёл правильный пример?","choices":["все","только Боря","только Аня и Боря","только Вера и Гриша","никто"],"key":"В","review":["Одна согласная перед -к-","«Оперетка» связана с «оперетта», а «финка» — с «финн». В обеих парах добавление -к- сопровождается исчезновением одной из двух букв.","«Каска» и «маска» не образованы от «касса» и «масса». Примеры Ани и Бори подходят."]},{"author":"Л. Фёдорова","question":"Миша разбивал на два класса прилагательные по их словообразовательным возможностям. В первый класс вошли слова: белый, жёлтый, крутой, во второй — красный, чёрный, простой. Какое прилагательное не попало ни в один из классов?","choices":["голубой","кривой","левый","синий","хромой"],"key":"Г","review":["Слова для признаков","Первый ряд образует слова на -изна: белизна, желтизна, крутизна. Во втором получается -ота: краснота, чернота, простота.","Сравним «голубизна», «кривизна», «левизна» и «хромота». У «синий» подходящее название признака «синева», с другим суффиксом."]},{"author":"Л. Фёдорова","question":"Каким словом можно продолжить ряд: всего, крест, крепко, перво, _____?","choices":["ничего","круг","просто","слабо","вечно"],"key":"В","review":["Слова с повтором","За каждым словом ряда можно повторить его с на-: «всего-навсего», «крест-накрест», «крепко-накрепко», «перво-наперво».","По этому же образцу говорят «просто-напросто». Слово «просто» продолжает ряд."]},{"author":"Е. Бикмаев","question":"Подумайте, почему одуванчик так называется, и выделите исторический корень в этом слове.","choices":["-ду-","-дув-","-дува-","-дуван-","-одуван-"],"key":"А","review":["Корень одуванчика","У цветка легко сдуть семена, поэтому его название связано со словами «дуть», «одувать», «сдувать».","Во всех этих формах повторяется часть -ду-. Именно она была историческим корнем слова."]},{"author":"М. Рубинштейн","question":"Слово носить можно перевести на язык иврит по-разному. Например, носить ботинки — на иврите линъоль наалаим, носить шапку — лахбош кова, носить жакет — лильбош жакет. (Слова языка иврит здесь записаны русскими буквами.) А как сказать на иврите носить пальто, носить шлем, носить кольцо?","choices":["меиль лильбош, касда лильбош, табаат линъоль","меиль лаанод, касда лахбош, табаат лаанод","лаанод меиль, лаанод касда, линъоль табаат","лильбош меиль, лаанод касда, линъоль табаат","лильбош меиль, лахбош касда, лаанод табаат"],"key":"Д","review":["Как сказать «носить»","Пальто надевают на туловище, как жакет. Поэтому используют «лильбош». Шлем, как шапку, носят на голове с глаголом «лахбош».","Кольцо не относится ни к одежде, ни к обуви. Для украшения нужен отдельный глагол «лаанод». Все три глагола в верном порядке даны в Д."]}], {"year":2024,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2024-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
